#!/usr/bin/env bash
# Droit à l'image : « Où j'apparais » (membre) et e-mail aux personnes taguées.
# Prérequis : apply-docs-tags-rapport.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-ou-j-apparais.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null | grep -qF "mine: protectedProcedure"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### Le rapport « Droit à l’image »" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tags-rapport.sh puis apply-docs-tags-rapport.sh"; exit 1; }
MODIFIED=(".env.example" "apps/web/src/app/(public)/profil/page.tsx" "apps/web/src/features/app-shell/UserMenu.tsx" "apps/web/src/instrumentation.ts" "e2e/env.mjs" "packages/backend/src/modules/media/services/canReadStorageKey.service.ts" "packages/backend/src/modules/mediaPeople/mediaPeople.service.ts" "packages/backend/src/modules/mediaPeople/publicRightsReport.service.ts" "packages/backend/src/modules/mediaPeople/router.ts" "packages/contracts/src/legal/mediaPeople.ts")
CREATED=("apps/web/src/app/(public)/profil/ou-j-apparais/page.tsx" "apps/web/src/features/image-consent/MyAppearances.tsx" "e2e/ou-j-apparais.spec.ts" "packages/backend/src/email/templates/mediaTagDigest.ts" "packages/backend/src/modules/mediaPeople/myAppearances.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "mine: protectedProcedure" "packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

